<script setup lang="ts">
import {confirmAction} from '../ui/confirm'
import {ref,computed} from 'vue'
import {request} from '../api'
import PrivatePreview from '../admin/PrivatePreview.vue'
import {bodyParts,bodyMedia} from './body'
const props=defineProps<{record:any;dirty:boolean;disabled:boolean}>(),emit=defineEmits<{(e:'removeMedia',id:string):void;(e:'removePlace',id:string):void;(e:'removeTag',id:string):void;(e:'changed'):void;(e:'cover',id:string):void}>()
const busy=ref(false),message=ref(''),references=ref<any[]>([])
const media=computed(()=>[...new Set([...props.record.connections.media.map((m:any)=>m.id),...(props.record.body_media_ids||[]),...bodyMedia(props.record.body,props.record.body_format||1).map(m=>m.id)])] as string[])
function mediaLabel(id:string){const ref=props.record.connections.media.find((m:any)=>m.id===id);return ref?.asset?.title||ref?.asset?.filename||bodyMedia(props.record.body,props.record.body_format||1).find(m=>m.id===id)?.alt||'本文图片'}
async function library(kind:'media'|'places'|'tags',id:string){if(props.dirty){message.value='请先保存或取消本文修改，再操作全局资源库；不会丢弃本地草稿。';return}busy.value=true;message.value='';references.value=[];try{
 if(kind==='tags'){const state=await request('/admin/tags/'+id+'/usage');references.value=state.records;if(!await confirmAction('全局删除标签，解除 '+state.count+' 篇文章的当前关联？不删除文章；历史身份保留且不自动复活。'))return;const tag=props.record.tags.find((t:any)=>t.id===id);await request('/admin/tags/'+id+'/delete-everywhere',{method:'POST',body:JSON.stringify({name:tag.name,confirmation_token:state.confirmation_token})})}
 else {const resource=await request('/admin/archive/'+kind+'/'+id);references.value=resource.usages||resource.references||[];if(!await confirmAction(kind==='media'?'从库中删除：将图片移入媒体回收站。仍有引用时服务器会阻止，不删除共享原图。继续？':'全局删除地点，不进入回收站；当前、行程、标记和历史引用存在时会被阻止。继续？'))return;await request('/admin/archive/'+kind+'/'+id,{method:'DELETE',body:JSON.stringify({expected_revision:resource.revision})})}
 message.value='资源库操作成功；正在重新读取本文。';emit('changed')
 }catch(e){message.value=String(e)}finally{busy.value=false}}
function removePlace(id:string){if((props.record.marked_places||[]).some((p:any)=>p.place_id===id)||props.record.body.includes(id)){message.value='此地点由 Markdown 标记引用。请明确编辑正文中的 @ 标记并保存后再移除；系统不会静默改原文，也不会通过断开关系后自动重建地点。';return}if((props.record.life?.activities||[]).some((a:any)=>a.place_id===id)||(props.record.life?.photos||[]).some((p:any)=>p.place_id===id)){message.value='行程或照片注记仍引用此地点，请先在同页行程/照片设置中明确解除。';return}emit('removePlace',id)}
async function removeMedia(id:string){if(props.record.body.includes(id)&&!bodyParts(props.record.body,props.record.body_format||1).some(p=>p.media?.id===id)){message.value='此图片使用旧版 Markdown/HTML 引用；请明确编辑源码移除并保存。系统不会猜测并改写旧正文。';return}if(await confirmAction('从本文移除这张图片的正文块、封面/画廊及当前行程、照片注记引用？需保存生效；原图和旧修订保留。'))emit('removeMedia',id)}
</script>
<template><details class="editor-resources"><summary>本文资源 · 移除引用与全局删除</summary><p>从本文移除随文章保存生效，不影响其他文章。全局删除需要单独确认；历史引用可能继续阻止删除。</p><fieldset :disabled="disabled||busy"><h4>图片与封面</h4><ul><li v-for="id in media" :key="id"><PrivatePreview :id="id" :alt="mediaLabel(id)"/><span>{{mediaLabel(id)}}</span><button type="button" class="quiet" @click="emit('cover',id)">设为封面</button><button type="button" class="quiet" @click="removeMedia(id)">从本文移除</button><button type="button" class="danger" @click="library('media',id)">从库中删除</button></li></ul><h4>地点</h4><ul><li v-for="p in record.connections.places" :key="p.id">{{p.name}}<button type="button" class="quiet" @click="removePlace(p.id)">从本文移除</button><button type="button" class="danger" @click="library('places',p.id)">从库中删除</button></li></ul><h4>标签</h4><ul><li v-for="t in record.tags||[]" :key="t.id">{{t.name}}<button type="button" class="quiet" @click="emit('removeTag',t.id)">从本文移除</button><button type="button" class="danger" @click="library('tags',t.id)">从库中删除</button></li></ul></fieldset><p v-if="message" role="status">{{message}}</p><ul v-if="references.length" aria-label="资源引用来源"><li v-for="(r,i) in references" :key="i">{{r.title||r.id}} · {{r.kind||'文章'}} {{r.revision?'修订 '+r.revision:''}}</li></ul></details></template>
<style scoped>.editor-resources{margin:18px 0}.editor-resources summary{cursor:pointer;min-height:44px;padding:10px 0}.editor-resources[open]>summary{font-weight:700}.editor-resources li{overflow-wrap:anywhere;margin:10px 0}.editor-resources :deep(img){width:100px;height:70px;object-fit:cover}.editor-resources button{margin:4px;min-height:40px}.editor-resources fieldset{min-width:0}</style>
